/* global URL */
import { el, button, badge, modal, dateText, notify, busy } from './utils.js';
import { api } from './service.js';
import { accountName, platform } from './model.js';
import { openImport } from './work-packages.js';
const editable=data=>data.roles?.some(role=>['operator','approver','admin'].includes(role));
const terminal=sequence=>['completed','stopped','failed','cancelled','rejected','expired','revoked'].includes(sequence.status)||/opt.?out|contact_replied|inbound_reply|suppressed|approval_revoked/.test(sequence.stopReason||'');
const time=value=>value?dateText(value):'Not scheduled';
const status=(value,kind)=>{const item=badge(value);if(value==='succeeded')item.textContent='Completed';if(value==='not_scheduled')item.textContent='Not scheduled';if(value==='executing')item.textContent=kind==='social.connect'?'Request in progress':'Sending';return item;};
function source(value,label){try{const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password)return null;return el('a',{class:'source-link',href:url.href,target:'_blank',rel:'noopener noreferrer',text:label||url.hostname});}catch{return null;}}
function progress(value={}){return `${value.succeeded??0} of ${value.total??0} steps completed · ${value.pending??0} pending · ${value.failed??0} failed · ${value.cancelled??0} cancelled`;}
function receipt(attempt){const value=attempt.receipt;const root=el('div',{class:'review-tile'},el('strong',{text:`Attempt ${attempt.attemptNo} · ${attempt.outcome}`}),el('small',{class:'field-help',text:time(attempt.finishedAt||attempt.startedAt)}));if(value?.providerMessageId){root.append(el('p',{text:`Native identifier: ${value.providerMessageId}`}));if(value.providerThreadId)root.append(el('p',{text:`Native thread: ${value.providerThreadId}`}));const link=source(value.raw?.url,'Open native receipt');if(link)root.append(link);}else root.append(el('p',{class:'field-help',text:'No confirmed native receipt for this attempt.'}));if(attempt.errorClass)root.append(el('p',{class:'field-help',text:`Provider result: ${attempt.errorClass}`}));return root;}
function stepView(step,index){const action=step.action;const requested=action?.channel||step.channel;const channel=requested==='email'?'Email':platform(requested).name;const account=step.account;const node=el('article',{class:'info-card','aria-label':`Sequence step ${index+1}`},el('div',{class:'review-heading'},el('h3',{text:`${index+1}. ${channel} · ${step.kind||'Message'}`}),status(action?.state||'not_scheduled',action?.kind)),el('p',{text:action?.text??step.text??'(No message text)'}),(action?.subject||step.subject)?el('p',{text:`Subject: ${action?.subject||step.subject}`}):null,el('p',{class:'field-help',text:`Account: ${account?accountName({sender:account.sender,externalAccountId:account.externalAccountId}):'Account unavailable'} · Recipient: ${action?.recipient||'Not resolved'}`}),el('p',{class:'field-help',text:`Scheduled: ${time(action?.dueAt)}${action?.notAfter?' · Execution ends '+time(action.notAfter):''}`}));
 if(step.waitFor==='connected')node.append(el('p',{class:'field-help',text:'Waits for verified LinkedIn connection acceptance.'}));if(step.waitHours)node.append(el('p',{class:'field-help',text:`Waits ${step.waitHours} hours ${index?'after the previous confirmed step':'after the plan start'}.`}));if(action?.reason)node.append(el('p',{class:'banner',text:action.reason}));if(!action)node.append(el('p',{class:'banner',text:'No executable action is linked to this step. Review the original work package.'}));
 for(const attempt of action?.attempts||[])node.append(receipt(attempt));if(!action?.attempts?.length)node.append(el('p',{class:'field-help',text:'No execution attempt recorded.'}));return node;
}
export function openSequence(sequenceId,data,refresh){const m=modal('Sequence details','Exact recipient, approved steps and native outcomes. This screen never sends or retries an effect.');const body=el('div',{class:'review-content','aria-live':'polite'},el('p',{class:'field-help',text:'Loading sequence details…'}));m.content.append(body);m.bottom.append(button('Close',m.close));
 const draw=sequence=>{body.replaceChildren(el('div',{class:'review-heading'},el('h2',{text:sequence.name}),status(sequence.status)),el('p',{class:'flow-note',text:progress(sequence.progress)}));const contact=sequence.contact;body.append(el('section',{class:'info-card'},el('h3',{text:contact?.name||sequence.contactName||'Recipient unavailable'}),el('p',{class:'field-help',text:contact?.points?.map(point=>`${point.channel||point.kind}: ${point.value}`).join(' · ')||'No verified contact channels returned.'}),contact?.notes?el('p',{text:contact.notes}):null,...(contact?.sources||[]).map(url=>source(url))));if(sequence.stopReason)body.append(el('p',{class:'banner',text:`Sequence hold: ${sequence.stopReason}`}));for(const[ index,step ]of(sequence.steps||[]).entries())body.append(stepView(step,index));
  const uncertain=(sequence.actions||[]).some(action=>['uncertain','reconciling','review','executing','claimed'].includes(action.state));const canResume=sequence.canResume===true&&sequence.status==='paused'&&!terminal(sequence)&&!uncertain;const controls=[button('Close',m.close)];const error=el('p',{class:'banner error',role:'alert',hidden:'',tabindex:'-1'});body.append(error);
  if(uncertain)body.append(el('p',{class:'banner',text:'An action is in flight or its outcome needs review. Resume stays held; no effect will be retried from here.'}));if(sequence.status==='paused'&&!canResume)body.append(el('p',{class:'field-help',text:`Resume held: ${sequence.resumeBlockedReason||'The sequence is stopped, in flight or awaiting required checks.'}`}));
  const change=(action,text)=>{const control=button(text,()=>busy(control,async()=>{error.hidden=true;try{const result=await api(action,{sequenceId});const next=result.sequence||(await api('outreach-review',{sequenceId})).sequence;draw(next);await refresh();notify(action==='outreach-pause'?'Sequence paused. In-flight work retains its recorded outcome.':'Sequence resumed within its existing approval and policy window.');}catch(problem){error.hidden=false;error.textContent=problem.message;error.focus();}}),action==='outreach-resume'?'primary':'');controls.push(control);};if(editable(data)&&sequence.canPause===true&&!terminal(sequence))change('outreach-pause','Pause sequence');if(editable(data)&&canResume)change('outreach-resume','Resume approved sequence');m.bottom.replaceChildren(...controls);
 };
 void api('outreach-review',{sequenceId}).then(value=>{if(!value.sequence)throw new Error('The server returned no sequence details.');draw(value.sequence);}).catch(error=>body.replaceChildren(el('p',{class:'banner error',role:'alert',text:`Sequence details unavailable: ${error.message}. Close and reopen after the workspace connection recovers.`})));return m;
}
export function renderOutreach(data,refresh){const root=el('div',{class:'stack'});if(data.errors?.['outreach-list'])root.append(el('p',{class:'banner error',role:'alert',text:'Sequence data could not refresh. Any shown progress is from the last successful snapshot.'}));root.append(el('section',{class:'info-card'},el('h2',{text:'Reviewed steps. Coordinated follow-ups.'}),el('p',{class:'flow-note',text:'Replies and opt-outs stop the original sequence across linked channels. Pausing keeps its exact approval; resuming requires fresh inbox, identity and policy checks.'}),editable(data)?button('Import outreach plan',()=>openImport(data,refresh),'small'):null));const sequences=data.sequences||[];const panel=el('section',{class:'content-panel'},el('div',{class:'panel-toolbar'},el('h2',{text:'Outreach sequences'}),el('span',{class:'muted',text:`${sequences.length.toLocaleString()} sequences`})));
 if(!sequences.length)panel.append(el('div',{class:'empty-state'},el('h3',{text:'Your next conversation starts here'}),el('p',{text:'Import real recipients, mapped accounts, reviewed content and schedules, then approve the exact plan.'})));for(const sequence of sequences){const person=data.people?.find(item=>item.id===sequence.contactId);panel.append(el('article',{class:'queue-card'},status(sequence.status),el('div',{},el('h3',{text:sequence.name||sequence.id}),el('p',{text:`${sequence.contactName||person?.name||'Recipient pending'} · ${progress(sequence.progress)}`}),el('small',{class:'field-help',text:sequence.stopReason||`Next step: ${sequence.currentStep??sequence.progress?.currentStep??'No step ready'} · ${time(sequence.scheduledFor)}`})),button('View sequence',()=>openSequence(sequence.id,data,refresh),'small')));}root.append(panel);return root;
}
